// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    // fuzzed params: an arbitrary sender `fromAddr` and a non-empty array length + element values
    // we cannot fuzz an address to be a recording contract, so we deploy a Recorder and pass its address as caddress
    // The property: for any from and any non-empty _tos array, C.transfer should return (not revert) and yield ok==true.
    function testFuzz_property(address fromAddr, uint8 len, uint256 seed) public {
        // keep length in a reasonable but wide domain, require non-empty as contract requires
        uint256 _len = bound(len, 1, 10); // at least 1 to satisfy require(_tos.length > 0)

        // build _tos array with fuzzed entries derived from seed
        address[] memory tos = new address[](_len);
        for (uint i = 0; i < _len; i++) {
            // create distinct-looking addresses from seed and index
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(seed, i)))));
        }

        // deploy a Recorder that implements transferFrom(address,uint256) signature to record calls
        Recorder rec = new Recorder();

        // Now call c.transfer and observe whether it reverts. The reference implementation must never revert for any of these inputs.
        bool ok;
        try c.transfer(fromAddr, address(rec), tos, 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: reference C should always return (ok == true) for any non-empty tos and any fromAddr.
        // The mutant with i<=_tos.length will sometimes revert (e.g., any _len>=1) and make ok==false; so this assertion
        // holds for the reference and is broken by the mutant for some inputs.
        assertTrue(ok);
    }
}

// Recorder: provides the exact function selector transferFrom(address,address,uint256)
// so that abi.decode on the callee side matches. It just records calls but does not revert.
contract Recorder {
    // simple counters to ensure it accepts calls
    uint public calls;
    address public lastFrom;
    address public lastTo; // although C encodes _tos[i] as the second address here because it encodes (from,_tos[i],v) into transferFrom(address,address,uint256)
    uint public lastV;

    // match the selector bytes4(keccak256("transferFrom(address,address,uint256)"))
    function transferFrom(address from, address to, uint256 v) external returns (bool) {
        calls += 1;
        lastFrom = from;
        lastTo = to;
        lastV = v;
        return true;
    }
}
